/// Per-unit identity hashes and the realignment they make possible.
///
/// A `.sta` sidecar stores counters positionally, by 1-based unit index. That
/// is enough while the deck is only ever edited inside the app (the editor
/// reports insertions and deletions, and `statsAfterInsert`/`statsAfterDelete`
/// shift the counters along). It is NOT enough for a deck edited somewhere
/// else — re-imported on the phone, regenerated by the Converter, hand-edited —
/// where every unit may have moved and index 7 no longer means the same word.
///
/// So each stored entry also carries a hash of the unit it was recorded for.
/// On load, [realignStatistics] diffs the stored hashes against the deck: units
/// that are still there keep their history wherever they moved to, units that
/// changed start clean, and the caller learns how much history was actually
/// lost so it can say so.
library;

import 'dart:convert';

import 'package:crypto/crypto.dart';

import '../engine/engine.dart';
import '../models/models.dart';

/// Length in hex characters of a [unitIdentityHash].
///
/// A 64-bit prefix of the SHA-256 digest: short enough that a deck of thousands
/// of units does not bloat its `.sta`, wide enough that an accidental collision
/// (which would silently move one unit's counters onto another) is not a
/// practical concern.
const int unitHashLength = 16;

/// Returns the identity hash of [unit] under [mask].
///
/// The input is the unit's category id plus the values of the fields that carry
/// a question or answer role in EITHER direction, in mask order, each tagged
/// with its field id. Remark fields are deliberately excluded, so rewriting a
/// remark never disturbs a unit's identity. Only the PLAIN text of a value
/// counts, so re-colouring or bolding an answer does not either.
///
/// Two consequences follow from this and are accepted knowingly: editing a
/// unit's question or answer text makes it a different unit (its statistics
/// start over), and changing a field's role in the mask re-hashes every unit in
/// the deck (statistics start over throughout).
String unitIdentityHash(LearningMask mask, LearningUnit unit) {
  // Each value is written LENGTH-PREFIXED (`|<fieldId>:<length>:<value>`), so
  // no field content can forge a field boundary and make two different units
  // hash alike — a bare separator character could, since a value may contain
  // anything the user can type.
  final StringBuffer buffer = StringBuffer()..write('c${unit.categoryId}');
  for (final (int fieldId, String text) in _identityValues(mask, unit)) {
    buffer.write('|$fieldId:${text.length}:$text');
  }
  final Digest digest = sha256.convert(utf8.encode(buffer.toString()));
  return digest.toString().substring(0, unitHashLength);
}

/// Returns the text [unitIdentityHash] covers for [unit] under [mask]: the
/// plain values of its question and answer fields, in mask order, one per
/// line. The category is not part of it.
///
/// For comparing how alike two units of one category are — the hash can only
/// say whether they are identical.
String unitIdentityText(LearningMask mask, LearningUnit unit) {
  return <String>[
    for (final (int _, String text) in _identityValues(mask, unit)) text,
  ].join('\n');
}

/// The field id and plain text of each of [unit]'s values that counts toward
/// its identity, in mask order. None when [mask] lacks the unit's category.
Iterable<(int, String)> _identityValues(
  LearningMask mask,
  LearningUnit unit,
) sync* {
  final CategoryDefinition? category = mask.categoryById(unit.categoryId);
  if (category == null) {
    return;
  }
  for (final FieldDefinition field in category.fields) {
    if (_countsTowardsIdentity(field)) {
      yield (field.id, unit.valueForFieldId(field.id).plainText);
    }
  }
}

/// Returns the identity hash of every unit in [deck], in deck order.
List<String> deckUnitHashes(LearningDeck deck) {
  return List<String>.unmodifiable(<String>[
    for (final LearningUnit unit in deck.units)
      unitIdentityHash(deck.mask, unit),
  ]);
}

/// Returns [statistics] with each entry's hash set from the unit it indexes.
///
/// Call this on every `.sta` write, so the file always describes the deck as it
/// stands right now. Entries whose index falls outside [deck] keep a null hash;
/// there is no unit to identify them with.
List<UnitStats> withUnitHashes(LearningDeck deck, List<UnitStats> statistics) {
  final List<String> hashes = deckUnitHashes(deck);
  return List<UnitStats>.unmodifiable(<UnitStats>[
    for (final UnitStats stats in statistics)
      stats.withIdentity(
        index: stats.index,
        hash: stats.index >= 1 && stats.index <= hashes.length
            ? hashes[stats.index - 1]
            : null,
      ),
  ]);
}

/// The outcome of realigning stored statistics onto a deck.
final class StatisticsRealignment {
  /// Creates a realignment result.
  const StatisticsRealignment({
    required this.statistics,
    required this.levelStatistics,
    required this.resetUnits,
  });

  /// Per-unit statistics, one entry per deck unit, in deck order.
  final List<UnitStats> statistics;

  /// Level-Learning statistics, re-indexed onto the same positions.
  ///
  /// Entries whose unit is gone are dropped, exactly as their counterparts in
  /// [statistics] are.
  final List<LevelUnitStats> levelStatistics;

  /// How many units' recorded statistics could not be carried over.
  ///
  /// A unit counts here only when it had actually been queried and no unit in
  /// the deck matches it any more — because its question or answer text was
  /// edited, or because it is no longer in the deck at all. Appending, moving
  /// or deleting never-queried units costs nothing and is not counted.
  final int resetUnits;

  /// Whether any recorded statistics were lost, i.e. worth telling the user.
  bool get hadResets => resetUnits > 0;
}

/// Carries [statistics] over to wherever their units now sit in [deck].
///
/// Matching is by [UnitStats.hash]: each deck unit claims the earliest stored
/// entry with its hash that no earlier unit has claimed, so identical units
/// keep their own counters in stored order. Deck units with no match start
/// clean, and the stored entries left over are reported through
/// [StatisticsRealignment.resetUnits].
///
/// A `.sta` written before hashes existed (no entry carries one) is loaded
/// positionally, exactly as it always was — an unhashed file says nothing about
/// identity, and guessing would be worse than the status quo. In a partially
/// hashed file (which nothing here writes, but a hand edit could produce) the
/// hashless entries cannot be identified, so they match nothing and are
/// reported as reset rather than quietly dropped.
StatisticsRealignment realignStatistics({
  required LearningDeck deck,
  required List<UnitStats> statistics,
  List<LevelUnitStats> levelStatistics = const <LevelUnitStats>[],
}) {
  final int unitCount = deck.units.length;
  final List<String> hashes = deckUnitHashes(deck);
  if (!statistics.any((UnitStats stats) => stats.hash != null)) {
    return StatisticsRealignment(
      statistics: withUnitHashes(deck, resizeUnitStats(statistics, unitCount)),
      levelStatistics: resizeLevelStats(levelStatistics, unitCount),
      resetUnits: 0,
    );
  }

  // Stored entries grouped by hash, each group in stored order, so identical
  // units are handed out first-come-first-served rather than arbitrarily.
  final Map<String, List<UnitStats>> available = <String, List<UnitStats>>{};
  for (final UnitStats stats in statistics) {
    final String? hash = stats.hash;
    if (hash == null) {
      continue;
    }
    available.putIfAbsent(hash, () => <UnitStats>[]).add(stats);
  }

  final Map<int, LevelUnitStats> levelByIndex = <int, LevelUnitStats>{
    for (final LevelUnitStats stats in levelStatistics) stats.index: stats,
  };
  final List<UnitStats> realigned = <UnitStats>[];
  final List<LevelUnitStats> realignedLevels = <LevelUnitStats>[];
  final Set<int> claimed = <int>{};

  for (var slot = 0; slot < unitCount; slot += 1) {
    final int index = slot + 1;
    final List<UnitStats>? candidates = available[hashes[slot]];
    if (candidates == null || candidates.isEmpty) {
      realigned.add(UnitStats(index: index, hash: hashes[slot]));
      continue;
    }
    final UnitStats source = candidates.removeAt(0);
    claimed.add(source.index);
    realigned.add(source.withIdentity(index: index, hash: hashes[slot]));
    final LevelUnitStats? levels = levelByIndex[source.index];
    if (levels != null) {
      realignedLevels.add(
        LevelUnitStats(index: index, dir1: levels.dir1, dir2: levels.dir2),
      );
    }
  }

  // A Level-Learning entry counts as progress in its own right: the engine
  // materializes one only once a session has put the unit on the ladder, so a
  // unit can carry real history there while its drill counters are still 0
  // (the same rule `hasRecordedStatistics` applies). Losing that silently
  // would be exactly the failure this whole mechanism exists to prevent.
  final int resetUnits = statistics
      .where(
        (UnitStats stats) =>
            !claimed.contains(stats.index) &&
            (stats.hasAttempts || levelByIndex.containsKey(stats.index)),
      )
      .length;

  return StatisticsRealignment(
    statistics: List<UnitStats>.unmodifiable(realigned),
    levelStatistics: List<LevelUnitStats>.unmodifiable(realignedLevels),
    resetUnits: resetUnits,
  );
}

/// Whether [field] contributes to a unit's identity.
///
/// Question and answer roles do, in either direction; a field that is a remark
/// in both directions does not.
bool _countsTowardsIdentity(FieldDefinition field) {
  return field.role1 != FieldRole.remark || field.role2 != FieldRole.remark;
}
